static String hx(const String&s){uint32_t a=2166136261u,b=0x9e3779b9u;for(size_t i=0;i<s.length();i++){a^=(uint8_t)s[i];a*=16777619u;b^=(a>>13)+(uint8_t)s[i];b*=0x85ebca6bu;}char o[25];snprintf(o,sizeof(o),"%08lx%08lx%08lx",(unsigned long)a,(unsigned long)b,(unsigned long)(a^b^0xA5A55A5Au));return o;}
static String rnd(size_t n=24){const char*c="ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";String r;for(size_t i=0;i<n;i++)r+=c[esp_random()%57];return r;}
static String esc(String s){s.replace("\\","\\\\");s.replace("\"","\\\"");s.replace("\n","\\n");s.replace("\r","\\r");return s;}
static void json(int code,const String&s){web.send(code,"application/json",s);}
static bool ok(const String&need=""){return token.length()&&millis()<tokenUntil&&web.header("X-Vortex-Session")==token&&(need.length()==0||role==need);}

