static void root(){web.send_P(200,"text/html",PAGE);}
static void login(){String r=web.arg("role"),u=web.arg("username"),p=web.arg("password");if(r=="admin"&&u.equalsIgnoreCase("dezavious")&&hx(p)==adminHash)role="admin",userName="Dezavious Ojelade";else if(r=="director"&&u.equalsIgnoreCase("director")&&hx(p)==directorHash)role="director",userName=directorName;else{return json(401,"{\"error\":\"Invalid login\"}");}token=rnd();tokenUntil=millis()+86400000UL;json(200,"{\"token\":\""+token+"\",\"role\":\""+role+"\",\"name\":\""+esc(userName)+"\"}");}
static void guest(){role="guest";userName=web.arg("name");if(!userName.length())userName="Guest User";token=rnd();tokenUntil=millis()+43200000UL;json(200,"{\"token\":\""+token+"\",\"role\":\"guest\",\"name\":\""+esc(userName)+"\"}");}
