static void addCommand(){if(!ok("admin"))return json(403,"{\"error\":\"Admin only\"}");String n=web.arg("name");if(n.length()<1)return json(400,"{\"error\":\"Empty command\"}");String list=pref.getString("cmds","");if(list.length())list+=';';list+=n;pref.putString("cmds",list);json(200,"{\"message\":\"Command added to the Vortex command registry.\"}");}
