static void elevenlabsKey(){if(!ok("admin"))return json(403,"{\"error\":\"Admin only\"}");String k=web.arg("key");if(k.length()<10)return json(400,"{\"error\":\"Invalid ElevenLabs API key\"}");elevenApiKey=k;pref.putString("eleven_key",elevenApiKey);json(200,"{\"message\":\"ElevenLabs voice configured for Vortex.\"}");}
static void elevenlabsTTS(){if(!ok())return json(401,"{\"error\":\"Session expired\"}");if(!elevenApiKey.length())return json(503,"{\"error\":\"ElevenLabs is not configured. Use Admin > ElevenLabs Voice.\"}");String text=web.arg("text");text.trim();if(!text.length())return json(400,"{\"error\":\"Empty text\"}");if(text.length()>1800)text=text.substring(0,1800);WiFiClientSecure client;client.setInsecure();HTTPClient http;String url=String("https://api.elevenlabs.io/v1/text-to-speech/")+ELEVEN_VOICE_ID+"?output_format=mp3_22050_32";if(!http.begin(client,url))return json(502,"{\"error\":\"Could not connect to ElevenLabs\"}");http.addHeader("xi-api-key",elevenApiKey);http.addHeader("Content-Type","application/json");String body=String("{\"text\":\"")+esc(text)+String("\",\"model_id\":\"")+ELEVEN_MODEL_ID+String("\",\"voice_settings\":{\"stability\":0.5,\"similarity_boost\":0.8,\"speed\":")+String(voiceRate,2)+String("}}");int code=http.POST(body);if(code!=200){String err=http.getString();http.end();return json(code>0?code:502,String("{\"error\":\"ElevenLabs TTS failed: ")+esc(err.substring(0,180))+"\"}");}int len=http.getSize();web.sendHeader("Cache-Control","no-store");web.setContentLength(len);web.send(200,"audio/mpeg","");WiFiClient* stream=http.getStreamPtr();uint8_t buf[1024];while(http.connected()&&(len>0||len==-1)){size_t avail=stream->available();if(avail){int n=stream->readBytes(buf,min(avail,(size_t)sizeof(buf)));web.sendContent((const char*)buf,n);if(len>0)len-=n;}else{delay(1);}}http.end();}

void vortexWebBegin(){pref.begin("vortex-auth",false);adminHash=pref.getString("admin","");directorHash=pref.getString("director",hx("director"));directorName=pref.getString("dname","");purposeText=pref.getString("purpose","Help Dezavious Ojelade with tasks, programming, learning, engineering, and everyday work.");voiceRate=pref.getFloat("rate",1.0f);elevenApiKey=pref.getString("eleven_key","");if(!adminHash.length()){String initial="Vortex-"+String((uint32_t)(ESP.getEfuseMac()&0xFFFFFFFF),HEX);adminHash=hx(initial);pref.putString("admin",adminHash);Serial.println("[VORTEX] FIRST RUN ADMIN: dezavious");Serial.println("[VORTEX] FIRST RUN PASSWORD: "+initial);}WiFi.mode(WIFI_AP);WiFi.softAP("Vortex-AI","VortexAI123");const char* hdrs[]={"X-Vortex-Session"};web.collectHeaders(hdrs,1);web.on("/",HTTP_GET,root);web.on("/api/login",HTTP_POST,login);web.on("/api/guest",HTTP_POST,guest);web.on("/api/chat",HTTP_POST,chat);web.on("/api/tts",HTTP_POST,elevenlabsTTS);web.on("/api/director/setup",HTTP_POST,setupDirector);web.on("/api/admin/purpose",HTTP_POST,purpose);web.on("/api/admin/command",HTTP_POST,command);web.on("/api/admin/director",HTTP_POST,directorPassword);web.on("/api/admin/add-command",HTTP_POST,addCommand);web.on("/api/admin/elevenlabs",HTTP_POST,elevenlabsKey);web.on("/api/settings",HTTP_POST,settings);web.begin();Serial.print("[VORTEX] Open http://");Serial.println(WiFi.softAPIP());}
